// --- CONFIGURAÇÕES DO SISTEMA ---
const VALOR_ALVO = 23;        // Temperatura padrão da sala (23°C)
const PORCENTAGEM_ERRO = 30;  // Tolerância de erro (30% cobre de ~16°C até ~30°C)
// ------------------------------------

// Inicializa as variáveis de contexto
let leituras = context.get('leituras') || [];
let bloqueado = context.get('bloqueado') || false;
let anomaliaDetectada = context.get('anomaliaDetectada') || false;
let picosDeAnomalia = context.get('picosDeAnomalia') || [];

// 1. VERIFICAÇÃO DE BLOQUEIO
// Se a janela de 10 minutos já fechou (20 leituras), ignora novas mensagens
if (bloqueado) {
    node.status({fill:"red", shape:"dot", text: "Bloqueado: Janela de 10min encerrada"});
    return null; 
}

// Captura e valida a temperatura que veio do MQTT
let tempAtual = Number(msg.payload);
if (isNaN(tempAtual)) {
    node.warn("Valor recebido não é um número válido: " + msg.payload);
    return null;
}

// 2. ACUMULAÇÃO DE DADOS (Adiciona primeiro no histórico)
leituras.push(tempAtual);

// --- VERIFICAÇÃO DE AUMENTO DE 3°C EM 2 MINUTOS ---
// Como o dado atual já está no array, comparamos com 4 posições atrás (2 minutos)
if (leituras.length >= 5) {
    let tempDoisMinutosAtras = leituras[leituras.length - 5];
    let diferenca = tempAtual - tempDoisMinutosAtras;

    if (diferenca >= 3) {
        anomaliaDetectada = true;
        // Guarda o registro de quando e quanto subiu no histórico interno
        picosDeAnomalia.push(`Subiu ${diferenca.toFixed(1)}°C em 2min (de ${tempDoisMinutosAtras}°C para ${tempAtual}°C)`);
        context.set('anomaliaDetectada', anomaliaDetectada);
        context.set('picosDeAnomalia', picosDeAnomalia);
    }
}

// Se ainda não chegou a 20 leituras, o código APENAS continua coletando em silêncio
if (leituras.length < 20) {
    context.set('leituras', leituras);
    node.status({fill:"blue", shape:"dot", text: `Coletando: ${leituras.length}/20 (Faltam ${(20 - leituras.length) * 30}s)`});
    return null; // Não envia mensagem final ainda, continua o fluxo de coleta
}

// 3. ATINGIU OS 10 MINUTOS (20 Leituras) -> AGORA SIM Bloqueia e calcula tudo
bloqueado = true;
context.set('bloqueado', bloqueado);
context.set('leituras', leituras); 

// --- CÁLCULO DA MEDIANA ---
let valoresOrdenados = [...leituras].sort((a, b) => a - b);
let metade = Math.floor(valoresOrdenados.length / 2);
let mediana = (valoresOrdenados[metade - 1] + valoresOrdenados[metade]) / 2; 

// --- VERIFICAÇÃO DA MARGEM DE ERRO DA MEDIANA ---
let limiteInferior = VALOR_ALVO * (1 - PORCENTAGEM_ERRO / 100);
let limiteSuperior = VALOR_ALVO * (1 + PORCENTAGEM_ERRO / 100);

let statusErroMediana = "";
let dentroDoLimiteMediana = false;

if (mediana < limiteInferior) {
    statusErroMediana = "Abaixo do limite permitido (Para menos)";
} else if (mediana > limiteSuperior) {
    statusErroMediana = "Acima do limite permitido (Para mais)";
} else {
    statusErroMediana = "Dentro do limite aceitável";
    dentroDoLimiteMediana = true;
}

// --- MONTAGEM DO PAYLOAD DE SAÍDA FINAL ---
msg.payload = {
    resultado: "Janela de 10 minutos concluída com sucesso.",
    totalLeituras: leituras.length,
    medianaCalculada: Number(mediana.toFixed(2)) + "°C",
    valorAlvo: VALOR_ALVO + "°C",
    limitesAceitaveis: {
        min: Number(limiteInferior.toFixed(2)) + "°C",
        max: Number(limiteSuperior.toFixed(2)) + "°C"
    },
    medianaDentroDoLimite: dentroDoLimiteMediana,
    statusMediana: statusErroMediana,

    // RELATÓRIO DO ERRO DE 3 GRAUS (Apenas exibido agora no final):
    ocorreuErroAumentoRapido: anomaliaDetectada,
    detalhesDoAumentoRapido: anomaliaDetectada ? picosDeAnomalia : "Nenhuma anomalia de pico térmico detectada.",

    historicoDasLeituras: leituras
};

// Atualização visual final do nó no Node-RED
if (anomaliaDetectada) {
    node.status({fill:"red", shape:"boom", text: "Finalizado (Com registro de anomalia)"});
} else {
    node.status({fill:"green", shape:"dot", text: "Finalizado com sucesso!"});
}

return msg;
